/**
 * Thrown when a pro-only feature is used without a valid license.
 * Consumer-facing — provides the feature name and upgrade URL for
 * actionable error messages in CLI output and CI logs.
 */
export class PaperJSXFeatureError extends Error {
    code;
    phase = "license";
    feature;
    upgradeUrl = "https://paperjsx.com/pricing";
    remediation;
    constructor(message, feature, code = "FEATURE_REQUIRES_UPGRADE") {
        super(message);
        this.name = "PaperJSXFeatureError";
        this.code = code;
        this.feature = feature ?? "unknown";
        this.remediation = `Provide a valid PaperJSX Pro license for "${this.feature}" or visit ${this.upgradeUrl}.`;
        Object.setPrototypeOf(this, new.target.prototype);
    }
    toJSON() {
        return {
            name: this.name,
            code: this.code,
            phase: this.phase,
            message: this.message,
            feature: this.feature,
            upgradeUrl: this.upgradeUrl,
            remediation: this.remediation,
        };
    }
}
