/**
 * Pro feature guard for @paperjsx/json-to-pdf.
 *
 * Free build (__PRO__=false): throws PaperJSXFeatureError (dead-code eliminated in free bundle).
 * Pro build (__PRO__=true): validates PAPERJSX_LICENSE_KEY. No key = throws. Invalid key = throws.
 */
import { AsyncLocalStorage } from "node:async_hooks";
import { validateLicenseKey, PaperJSXFeatureError } from '@paperjsx/license';

declare const __PRO__: boolean;
export const IS_PRO = typeof __PRO__ !== "undefined" ? __PRO__ : false;

const pdfLicenseContext = new AsyncLocalStorage<{ licenseKey?: string }>();

export function withPdfLicenseKey<T>(licenseKey: string | undefined, callback: () => T): T {
  return pdfLicenseContext.run({ licenseKey }, callback);
}

function resolvePdfLicenseKey(licenseKey?: string): string | undefined {
  return licenseKey ?? pdfLicenseContext.getStore()?.licenseKey ?? process.env.PAPERJSX_LICENSE_KEY;
}

function getPdfLicenseValidationResult(licenseKey?: string) {
  const key = resolvePdfLicenseKey(licenseKey);
  if (!key) {
    return {
      key: undefined,
      result: { valid: false, error: "No license key provided" },
    };
  }

  return {
    key,
    result: validateLicenseKey(key, "pdf"),
  };
}

export function hasPdfProLicense(licenseKey?: string): boolean {
  if (!IS_PRO) {
    return false;
  }
  return getPdfLicenseValidationResult(licenseKey).result.valid;
}

export function assertPdfPackageLicense(feature = "PDF rendering", licenseKey?: string): void {
  if (!IS_PRO) {
    return;
  }

  const { key, result } = getPdfLicenseValidationResult(licenseKey);
  if (!key) {
    throw new PaperJSXFeatureError(
      `"${feature}" requires a valid PaperJSX Pro license key. Set PAPERJSX_LICENSE_KEY. See https://paperjsx.com/pricing`,
      feature,
      "LICENSE_REQUIRED",
    );
  }
  if (!result.valid) {
    throw new PaperJSXFeatureError(
      `"${feature}": ${result.error}`,
      feature,
      "LICENSE_INVALID",
    );
  }
}

export function requirePdfPro(feature: string, licenseKey?: string): void {
  if (!IS_PRO) {
    throw new PaperJSXFeatureError(
      `"${feature}" requires @paperjsx/json-to-pdf-pro. See https://paperjsx.com/pricing`,
      feature,
    );
  }
  assertPdfPackageLicense(feature, licenseKey);
}
